(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { distance:$('distance'), progress:$('progressFill'), score:$('score'), combo:$('combo'), shards:$('shards'), overlay:$('overlay'), end:$('endOverlay'), toast:$('toast'), burstFill:$('burstFill'), burstLabel:$('burstLabel'), wind:$('wind') };
  const keys = { leanBack:false, leanForward:false, throttle:false, burst:false };
  const ROUTE = 10800, WHEEL = 18, WHEELBASE = 96;
  const shardsAt = [690, 1690, 2910, 4080, 5450, 6810, 8240, 9720];
  const gapsAt = [[2480,2710],[6200,6420],[8240,8470]];
  let W=1000,H=600,DPR=1,scale=1,last=0,raf=0,gameOn=false,finished=false;
  let world=0,speed=0,angle=0,angular=0,burstCharge=0,burstTime=0,airY=0,airV=0,shards=[],score=0,streak=0,bestStreak=0,shardCount=0,hitFlash=0,toastTimer=0,toastLock=0,windStrength=12,soundOn=true,audioCtx=null,lastShard=-1;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const lerp=(a,b,t)=>a+(b-a)*t;
  function resize(){const r=canvas.getBoundingClientRect();DPR=Math.min(devicePixelRatio||1,2);scale=r.width/1000;W=1000;H=r.height/scale;canvas.width=Math.round(r.width*DPR);canvas.height=Math.round(r.height*DPR);ctx.setTransform(DPR/scale,0,0,DPR/scale,0,0);}
  window.addEventListener('resize',resize); resize();
  const gapFor = x => gapsAt.find(g=>x>=g[0]-12&&x<=g[1]+12);
  function groundY(x){return H*.735 + Math.sin(x*.0014)*20 + Math.sin(x*.0036+1)*9 + Math.sin(x*.00048+2)*26;}
  function surfaceY(x){const g=gapFor(x);if(g)return groundY(g[0]);return groundY(x);}
  function newRun(){world=0;speed=0;angle=0;angular=0;burstCharge=0;burstTime=0;airY=0;airV=0;score=0;streak=0;bestStreak=0;shardCount=0;hitFlash=0;shards=shardsAt.map(x=>({x,got:false,missed:false}));lastShard=-1;finished=false;gameOn=true;ui.end.classList.add('hidden');ui.overlay.classList.add('hidden');toast('GO FIND YOUR LINE',1300);last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);}
  function toast(text,duration=1500){if(performance.now()<toastLock)return;ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=duration;}
  function playTone(freq=520,duration=.08,type='sine'){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch{}}
  function startBurst(){if(!gameOn||burstCharge<1||burstTime>0)return;burstCharge=0;burstTime=1.16;airV=-330;speed=Math.min(410,speed+46);playTone(360,.3,'triangle');toast('THERMAL BURST — UPDRAFT!',1050);}
  function crash(message){if(!gameOn)return;gameOn=false;finished=true;playTone(110,.35,'sawtooth');$('endKicker').textContent='RUN ENDED';$('endTitle').innerHTML='DUST<br><em>SETTLED.</em>';$('endCopy').textContent=message;$('finalScore').textContent=String(Math.floor(score)).padStart(6,'0');$('finalShards').textContent=`${shardCount} / 8`;$('finalCombo').textContent=`${Math.floor(bestStreak)} m`;ui.end.classList.remove('hidden');}
  function finish(){gameOn=false;finished=true;playTone(790,.22,'triangle');$('endKicker').textContent='RUN COMPLETE';$('endTitle').innerHTML='PASS<br><em>CONQUERED.</em>';$('endCopy').textContent=shardCount===8?'Every signal recovered. The ridge is yours.':`You made the pass, but found ${shardCount} of 8 signal shards.`;$('finalScore').textContent=String(Math.floor(score)).padStart(6,'0');$('finalShards').textContent=`${shardCount} / 8`;$('finalCombo').textContent=`${Math.floor(bestStreak)} m`;ui.end.classList.remove('hidden');}
  function update(dt){if(!gameOn)return;dt=Math.min(dt,.035);const back=keys.leanBack?1:0,forward=keys.leanForward?1:0,throttle=keys.throttle?1:0;
    speed += (throttle?178: -28)*dt; speed=clamp(speed,0,370);
    if(speed>25)world+=speed*dt;
    const wind=Math.sin(world*.0007+1)*.48;
    angular += (back*3.35-forward*3.8 - Math.sin(angle)*2.1 - angle*.7 + wind*.22)*dt;
    angular *= Math.pow(.982,dt*60);angle=clamp(angle+angular*dt,-.18,1.12);
    const ground=surfaceY(world); if(burstTime>0){burstTime-=dt;airV+=680*dt;airY+=airV*dt;if(airY>0){airY=0;airV=0;burstTime=0;}}
    else if(airY<0){airV+=750*dt;airY+=airV*dt;if(airY>=0){airY=0;airV=0;}}
    const wheelie=angle>.22 && speed>80 && airY===0;
    if(wheelie){streak+=speed*dt/9;bestStreak=Math.max(bestStreak,streak);score+=speed*dt*.14;burstCharge=Math.min(1,burstCharge+dt*.22);}
    else streak=0;
    for(let i=0;i<shards.length;i++){let s=shards[i];if(s.got||s.missed)continue;const dx=s.x-world;if(Math.abs(dx)<48){if(wheelie&&angle>.27){s.got=true;shardCount++;score+=500;lastShard=i;playTone(690+i*45,.16,'sine');toast('SIGNAL SHARD +500',1000);}else if(dx<0){s.missed=true;toast('MISSED A SIGNAL — LIFT THAT FRONT',1150);}}}
    const gap=gapFor(world);if(gap && burstTime<=0&&airY===0 && speed>100){crash('The washout took your front wheel. Save a thermal burst for the broken ground.');return;}
    // Scattered glass-rock hazards reward a controlled lift.
    const rockX=[1290,3520,4960,7330,9040].find(x=>Math.abs(world-x)<speed*dt+9);
    if(rockX && angle<.2 && airY===0){crash('A glass-rock caught your front tire. Lean back to clear the pass.');return;}
    if(world>=ROUTE){finish();return;}
    if(hitFlash>0)hitFlash-=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
    updateHud(wheelie);
  }
  function updateHud(wheelie){let meters=Math.floor(world/9);ui.distance.textContent=meters.toLocaleString();ui.progress.style.width=`${clamp(world/ROUTE*100,0,100)}%`;ui.score.textContent=String(Math.floor(score)).padStart(6,'0');ui.combo.textContent=wheelie?`◇ ${Math.floor(streak)} m STREAK`:'◇ 0 STREAK';ui.shards.textContent=shardCount;ui.burstFill.style.width=`${burstCharge*100}%`;ui.burstLabel.textContent=burstTime>0?'ACTIVE':burstCharge>=1?'READY':'CHARGING';ui.wind.textContent=`↗ ${Math.round(windStrength+Math.sin(world*.0007+1)*7)}`;}
  function loop(now){const dt=(now-last)/1000;last=now;update(dt);draw();if(gameOn)raf=requestAnimationFrame(loop);}
  function draw(){ctx.clearRect(0,0,W,H);drawSky();const camera=world-330;drawMountains(camera);drawRoad(camera);drawObjects(camera);drawShardField(camera);drawBike(330,surfaceY(world)-WHEEL+airY,angle);drawDust(330,surfaceY(world),camera);if(hitFlash>0){ctx.fillStyle=`rgba(255,118,71,${Math.min(.22,hitFlash)})`;ctx.fillRect(0,0,W,H)}}
  function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#506c79');g.addColorStop(.42,'#e58d70');g.addColorStop(.73,'#f1ba83');g.addColorStop(1,'#c7a375');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const sunX=750,sunY=H*.37;const halo=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,165);halo.addColorStop(0,'#ffe6adcc');halo.addColorStop(.18,'#ffd19d61');halo.addColorStop(1,'#ffc98d00');ctx.fillStyle=halo;ctx.fillRect(sunX-170,sunY-170,340,340);ctx.fillStyle='#ffdaa4';ctx.beginPath();ctx.arc(sunX,sunY,31,0,Math.PI*2);ctx.fill();
    // Thin wind ribbons signal the new thermal mechanic.
    ctx.strokeStyle='#fff0cc38';ctx.lineWidth=1;for(let i=0;i<5;i++){let y=H*.2+i*19,x=(world*.11+i*193)%1200-100;ctx.beginPath();ctx.moveTo(x,y);ctx.bezierCurveTo(x+60,y-8,x+108,y+8,x+180,y-4);ctx.stroke();}}
  function drawMountains(camera){const layers=[{base:.65,amp:65,color:'#687b79',freq:.0011,par:.12},{base:.71,amp:62,color:'#566969',freq:.0016,par:.25},{base:.78,amp:48,color:'#42585a',freq:.0022,par:.39}];for(let j=0;j<layers.length;j++){let l=layers[j];ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+10;x+=12){let wx=x+camera*l.par;let y=H*l.base - Math.abs(Math.sin(wx*l.freq+j*2.7))*l.amp - Math.sin(wx*l.freq*.39+j)*l.amp*.46;ctx.lineTo(x,y);}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=l.color;ctx.fill();}
    // distant faceted glass outcrops
    for(let i=0;i<9;i++){let x=((i*147+700-camera*.33)%1300+1300)%1300-100,y=H*(.56+(i%3)*.035);ctx.fillStyle=i%2?'#89a59d42':'#d7c49c38';ctx.beginPath();ctx.moveTo(x-25,y);ctx.lineTo(x-5,y-40-(i%3)*13);ctx.lineTo(x+2,y-18);ctx.lineTo(x+18,y-58-(i%4)*8);ctx.lineTo(x+30,y);ctx.closePath();ctx.fill();}}
  function roadHeight(x){return surfaceY(x)}
  function drawRoad(camera){const start=Math.floor(camera/20)*20,end=camera+W+60,step=16;
    // Dusty land under the course.
    ctx.beginPath();ctx.moveTo(0,H);for(let x=start;x<=end;x+=step){ctx.lineTo(x-camera,roadHeight(x)+75)}ctx.lineTo(W,H);ctx.closePath();let dirt=ctx.createLinearGradient(0,H*.67,0,H);dirt.addColorStop(0,'#65534a');dirt.addColorStop(1,'#26383a');ctx.fillStyle=dirt;ctx.fill();
    // Asphalt ribbon with explicit washout gaps.
    for(let x=start;x<end;x+=step){const mid=x+step/2;if(gapFor(mid))continue;const a=x-camera,b=x+step-camera,y1=roadHeight(x),y2=roadHeight(x+step);ctx.beginPath();ctx.moveTo(a,y1);ctx.lineTo(b,y2);ctx.lineTo(b,y2+83);ctx.lineTo(a,y1+83);ctx.closePath();ctx.fillStyle='#37474a';ctx.fill();ctx.strokeStyle='#e7c68c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a,y1);ctx.lineTo(b,y2);ctx.stroke();}
    // broken asphalt edges and painted center slashes
    for(let x=start;x<end;x+=112){if(gapFor(x))continue;let sx=x-camera,y=roadHeight(x)+42;ctx.strokeStyle='#d2b5799a';ctx.lineWidth=2;ctx.setLineDash([17,16]);ctx.beginPath();ctx.moveTo(sx,y);ctx.lineTo(sx+50,y+Math.sin(x*.0014)*4);ctx.stroke();ctx.setLineDash([]);}
    for(const g of gapsAt){if(g[1]<camera||g[0]>camera+W)continue;const x=g[0]-camera,w=g[1]-g[0],y=groundY(g[0]);ctx.fillStyle='#142a30';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+w,y+8);ctx.lineTo(x+w+25,H);ctx.lineTo(x-20,H);ctx.fill();ctx.strokeStyle='#f1845a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-2,y);ctx.lineTo(x+15,y+4);ctx.moveTo(x+w-12,y+5);ctx.lineTo(x+w+6,y+9);ctx.stroke();}
  }
  function drawObjects(camera){for(let x=250;x<ROUTE+500;x+=480){let sx=x-camera;if(sx<-90||sx>W+90)continue;let y=groundY(x); // roadside crystal shards
      const h=27+(Math.sin(x)*.5+.5)*26;ctx.fillStyle='#9bd6c544';ctx.beginPath();ctx.moveTo(sx-11,y-1);ctx.lineTo(sx-4,y-h*.72);ctx.lineTo(sx+2,y-h);ctx.lineTo(sx+13,y-4);ctx.closePath();ctx.fill();ctx.strokeStyle='#e4f0cb66';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(sx+2,y-h);ctx.lineTo(sx+3,y);ctx.stroke();
      if(x%960<40){ctx.fillStyle='#30474a';ctx.fillRect(sx+58,y-36,4,36);ctx.fillStyle='#d8f56a';ctx.beginPath();ctx.arc(sx+60,y-39,4,0,Math.PI*2);ctx.fill();}}
    const rocks=[1290,3520,4960,7330,9040];rocks.forEach((x,i)=>{const sx=x-camera;if(sx<-50||sx>W+50)return;let y=groundY(x);ctx.fillStyle='#bd755a';ctx.beginPath();ctx.moveTo(sx-16,y);ctx.lineTo(sx-11,y-13);ctx.lineTo(sx+1,y-22);ctx.lineTo(sx+16,y-10);ctx.lineTo(sx+20,y);ctx.closePath();ctx.fill();ctx.strokeStyle='#e99a70';ctx.lineWidth=1;ctx.stroke();});
  }
  function drawShardField(camera){shards.forEach(s=>{if(s.got||s.missed)return;let x=s.x-camera;if(x<-50||x>W+50)return;let y=groundY(s.x)-108+Math.sin(performance.now()*.003+s.x)*5;ctx.save();ctx.translate(x,y);ctx.rotate(Math.PI/4);ctx.shadowColor='#d8f56a';ctx.shadowBlur=15;ctx.fillStyle='#d8f56a';ctx.fillRect(-7,-7,14,14);ctx.shadowBlur=0;ctx.fillStyle='#fff6c4';ctx.fillRect(-3,-3,6,6);ctx.restore();ctx.strokeStyle='#d8f56a52';ctx.beginPath();ctx.arc(x,y,18,0,Math.PI*2);ctx.stroke();});}
  function wheel(x,y,r){ctx.fillStyle='#152228';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#dce7dc';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,r-3,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#a5b2ab';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,r*.58,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#dbe4d9aa';for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(x+Math.cos(a)*3,y+Math.sin(a)*3);ctx.lineTo(x+Math.cos(a)*(r-4),y+Math.sin(a)*(r-4));ctx.stroke();}ctx.fillStyle='#d8f56a';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();}
  function drawBike(x,y,a){ctx.save();ctx.translate(x,y);ctx.rotate(-a);let fx=WHEELBASE,fy=-Math.sin(a)*WHEELBASE; // pivot is rear hub
    // frame, fork and wheels
    ctx.strokeStyle='#d8f56a';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(39,-24);ctx.lineTo(fx,fy);ctx.moveTo(39,-24);ctx.lineTo(31,-55);ctx.lineTo(-2,-51);ctx.lineTo(0,0);ctx.moveTo(31,-55);ctx.lineTo(fx-3,fy-6);ctx.stroke();
    ctx.strokeStyle='#1b2529';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-2,-51);ctx.lineTo(18,-51);ctx.moveTo(70,fy-17);ctx.lineTo(83,fy-17);ctx.stroke();ctx.strokeStyle='#fa7651';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(43,-27);ctx.lineTo(58,-31);ctx.stroke();
    wheel(0,0,WHEEL);wheel(fx,fy,WHEEL);
    // rider torso / helmet, pose leans into the balance
    ctx.strokeStyle='#e8e4d7';ctx.lineWidth=9;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(32,-55);ctx.lineTo(16,-76);ctx.lineTo(-4,-67);ctx.moveTo(16,-76);ctx.lineTo(39,-79);ctx.stroke();
    ctx.strokeStyle='#a8bbb0';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(16,-76);ctx.lineTo(45,-51);ctx.moveTo(40,-78);ctx.lineTo(64,fy-13);ctx.stroke();
    ctx.fillStyle='#ff7647';ctx.beginPath();ctx.arc(4,-88,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f2d3a9';ctx.beginPath();ctx.arc(7,-89,8,Math.PI*1.1,Math.PI*1.95);ctx.fill();ctx.fillStyle='#1d3035';ctx.fillRect(7,-91,12,4);
    if(burstTime>0){ctx.fillStyle='#ffad67';ctx.beginPath();ctx.moveTo(17,2);ctx.lineTo(4,27+Math.random()*9);ctx.lineTo(26,3);ctx.fill();ctx.fillStyle='#f7edaa';ctx.beginPath();ctx.moveTo(18,3);ctx.lineTo(15,18);ctx.lineTo(23,3);ctx.fill();}
    ctx.restore();}
  function drawDust(x,y,camera){if(speed>80){ctx.globalAlpha=.16;ctx.fillStyle='#f7d8a2';for(let i=0;i<4;i++){let px=x-45-i*14,py=y+8+(i%2)*5;ctx.beginPath();ctx.arc(px,py,2+i%3,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}}

  const map={ArrowLeft:'leanBack',KeyA:'leanBack',ArrowRight:'leanForward',KeyD:'leanForward',ArrowUp:'throttle',KeyW:'throttle',KeyZ:'throttle'};
  window.addEventListener('keydown',e=>{if(map[e.code]){keys[map[e.code]]=true;e.preventDefault()}if(e.code==='Space'){if(gameOn){startBurst();e.preventDefault()}else if(!finished)newRun()}if(e.code==='Enter'&&!gameOn&&!finished)newRun();});
  window.addEventListener('keyup',e=>{if(map[e.code]){keys[map[e.code]]=false;e.preventDefault()}});
  window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
  document.querySelectorAll('.mobile-controls button').forEach(button=>{const action=button.dataset.control;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(action==='burst')startBurst();else keys[action]=true;});const release=e=>{e.preventDefault();if(action!=='burst')keys[action]=false};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);});
  $('startBtn').addEventListener('click',()=>newRun());$('againBtn').addEventListener('click',()=>newRun());
  $('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').innerHTML=soundOn?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';if(soundOn)playTone(540,.08)});
  // Render the route before the first input, including a subtle idle breeze.
  shards=shardsAt.map(x=>({x,got:false,missed:false}));draw();
})();

